/// Runs the account ledger.
///
/// The balance starts at `start`. For each `k`, operation `k` has kind
/// `kinds[k]` and amount `amounts[k]` and is applied in order:
/// - kind 0: deposit `amount` (rejected if the new balance would exceed i64::MAX);
/// - kind 1: withdraw `amount` (rejected if `amount` > balance);
/// - kind 2: interest, the balance grows by `(balance / 100) * amount`
///   (integer division) (rejected if the new balance would exceed i64::MAX);
/// - kind 3: fee, the amount is taken from the balance, or the whole balance
///   if it is smaller (never rejected).
///
/// After each operation one line is printed: the new balance, or `-1` if the
/// operation was rejected (a rejected operation leaves the balance unchanged).
///
/// Returns the final balance.
pub fn ledger(kinds: &[i64], amounts: &[i64], start: i64) -> i64 {
    let (balance, lines) = run_ledger(kinds, amounts, start);
    for line in &lines {
        println!("{}", line);
    }
    balance
}

/// Core logic of [`ledger`] without printing.
///
/// Returns the final balance and the sequence of values that would be
/// printed after each operation (the new balance, or `-1` if rejected).
fn run_ledger(kinds: &[i64], amounts: &[i64], start: i64) -> (i64, Vec<i64>) {
    // Invariant: the balance is always in [0, i64::MAX].
    let mut balance = start;
    let mut lines = Vec::with_capacity(kinds.len());
    for k in 0..kinds.len() {
        let amount = amounts[k];
        let outcome = apply_op(kinds[k], balance, amount);
        match outcome {
            Some(nb) => {
                balance = nb;
                lines.push(nb);
            }
            None => lines.push(-1),
        }
    }
    (balance, lines)
}

/// Apply one operation to `balance`.
///
/// Returns `Some(new_balance)` if the operation is applied and
/// `None` if it is rejected (rejection leaves the balance unchanged).
fn apply_op(kind: i64, balance: i64, amount: i64) -> Option<i64> {
    match kind {
        // Deposit: rejected on overflow (amount >= 0, balance >= 0,
        // so checked_add overflow is exactly "exceeds i64::MAX").
        0 => balance.checked_add(amount),
        // Withdraw: rejected if the amount is greater than the balance.
        1 => {
            if amount > balance {
                None
            } else {
                Some(balance - amount)
            }
        }
        // Interest: growth is (balance / 100) * amount; rejected if either
        // the product or the new balance overflows i64.
        2 => (balance / 100)
            .checked_mul(amount)
            .and_then(|growth| balance.checked_add(growth)),
        // Fee: take the amount, or the whole balance if it is smaller;
        // never rejected (balance, amount >= 0, so the result is >= 0).
        3 => Some(if amount < balance { balance - amount } else { 0 }),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Sample one of the given values uniformly (array taken by value so the
    /// returned strategy is 'static).
    fn idx<const N: usize>(v: [i64; N]) -> impl Strategy<Value = i64> {
        (0..N as u32).prop_map(move |i| v[i as usize])
    }

    /// Reference implementation using i128 arithmetic (no overflow possible:
    /// b, a <= i64::MAX and (b / 100) * a <= (i64::MAX / 100) * i64::MAX < i128::MAX).
    fn reference(kinds: &[i64], amounts: &[i64], start: i64) -> (i64, Vec<i64>) {
        const MAX: i128 = i64::MAX as i128;
        let mut b = start as i128;
        let mut lines = Vec::with_capacity(kinds.len());
        for (k, a) in kinds.iter().zip(amounts.iter()) {
            let a = *a as i128;
            let mut ok = true;
            match *k {
                0 => {
                    if b + a > MAX {
                        ok = false;
                    } else {
                        b += a;
                    }
                }
                1 => {
                    if a > b {
                        ok = false;
                    } else {
                        b -= a;
                    }
                }
                2 => {
                    let inc = (b / 100) * a;
                    if b + inc > MAX {
                        ok = false;
                    } else {
                        b += inc;
                    }
                }
                3 => {
                    if a < b {
                        b -= a;
                    } else {
                        b = 0;
                    }
                }
                _ => {}
            }
            lines.push(if ok { b as i64 } else { -1 });
        }
        (b as i64, lines)
    }

    #[test]
    fn empty_ledger() {
        assert_eq!(run_ledger(&[], &[], 5), (5, vec![]));
        assert_eq!(ledger(&[], &[], 0), 0);
    }

    #[test]
    fn simple_operations() {
        let (bal, lines) = run_ledger(
            &[0, 1, 2, 3],
            &[100, 40, 5, 1000],
            10,
        );
        // 10 + 100 = 110; 110 - 40 = 70; 70 + (70/100)*5 = 70 + 0 = 70;
        // 70 - 1000 -> 0 (fee capped at balance).
        assert_eq!(bal, 0);
        assert_eq!(lines, vec![110, 70, 70, 0]);
    }

    #[test]
    fn interest_growth() {
        // 250 -> (250 / 100) * 3 = 6 -> 256.
        assert_eq!(run_ledger(&[2], &[3], 250), (256, vec![256]));
        // 199 -> 1 * 100 = 100 -> 299 (integer division: 199/100 == 1).
        assert_eq!(run_ledger(&[2], &[100], 199), (299, vec![299]));
        // zero growth is accepted, not rejected.
        assert_eq!(run_ledger(&[2], &[7], 99), (99, vec![99]));
        assert_eq!(run_ledger(&[2], &[0], i64::MAX), (i64::MAX, vec![i64::MAX]));
    }

    #[test]
    fn withdrawals() {
        // exact withdrawal ok
        assert_eq!(run_ledger(&[1], &[10], 10), (0, vec![0]));
        // overdraw rejected, balance unchanged
        assert_eq!(run_ledger(&[1], &[11], 10), (10, vec![-1]));
        assert_eq!(run_ledger(&[1], &[0], 10), (10, vec![10]));
    }

    #[test]
    fn overflow_rejections() {
        // deposit that would exceed i64::MAX
        assert_eq!(
            run_ledger(&[0], &[10], i64::MAX - 5),
            (i64::MAX - 5, vec![-1])
        );
        // deposit landing exactly on i64::MAX is accepted
        assert_eq!(run_ledger(&[0], &[5], i64::MAX - 5), (i64::MAX, vec![i64::MAX]));
        // deposit of 0 at i64::MAX is accepted
        assert_eq!(run_ledger(&[0], &[0], i64::MAX), (i64::MAX, vec![i64::MAX]));
        // interest that would exceed i64::MAX
        assert_eq!(run_ledger(&[2], &[100], i64::MAX), (i64::MAX, vec![-1]));
        // interest growth itself overflows i64 (product check, not just sum)
        // (i64::MAX / 100) * i64::MAX >> i64::MAX
        assert_eq!(
            run_ledger(&[2], &[i64::MAX], i64::MAX),
            (i64::MAX, vec![-1])
        );
        // after a rejection, state is unchanged for the next operation
        assert_eq!(
            run_ledger(&[0, 1], &[i64::MAX, 3], i64::MAX - 5),
            (i64::MAX - 8, vec![-1, i64::MAX - 8])
        );
    }

    #[test]
    fn fees_never_rejected() {
        assert_eq!(apply_op(3, 10, 25), Some(0));
        assert_eq!(apply_op(3, 7, i64::MAX), Some(0));
        assert_eq!(apply_op(3, 7, 0), Some(7));
        assert_eq!(apply_op(3, 10, 4), Some(6));
        assert_eq!(apply_op(3, 0, 5), Some(0));
        assert_eq!(run_ledger(&[3], &[25], 10), (0, vec![0]));
        assert_eq!(run_ledger(&[3], &[i64::MAX], 7), (0, vec![0]));
        assert_eq!(run_ledger(&[3], &[0], 7), (7, vec![7]));
    }

    #[test]
    fn ledger_prints_and_returns() {
        // Also exercises the printing path (lines appear in test output).
        assert_eq!(ledger(&[0, 1, 2, 3], &[100, 40, 5, 1000], 10), 0);
        assert_eq!(ledger(&[1], &[11], 10), 10);
    }

    /// Amount strategy mixing small random values with boundary values so the
    /// overflow paths are exercised often.
    fn amt() -> impl Strategy<Value = i64> {
        prop_oneof![
            8 => 0..=10_000_i64,
            3 => 0..=i64::MAX / 2,
            2 => idx([
                0,
                1,
                99,
                100,
                101,
                i64::MAX,
                i64::MAX - 1,
                i64::MAX - 100,
                i64::MAX / 100,
                i64::MAX / 100 - 1,
                (i64::MAX / 100) * 100,
            ]),
        ]
    }

    proptest! {
        #[test]
        fn matches_reference(
            kinds in prop::collection::vec(0..=3_i64, 0..30),
            amounts in prop::collection::vec(amt(), 0..30),
            start in prop_oneof![
                7 => 0..=100_000_i64,
                3 => idx([
                    0,
                    100,
                    99,
                    i64::MAX,
                    i64::MAX - 1,
                    i64::MAX - 1000,
                ]),
            ],
        ) {
            let n = kinds.len().min(amounts.len());
            let kinds = &kinds[..n];
            let amounts = &amounts[..n];
            prop_assert_eq!(
                run_ledger(kinds, amounts, start),
                reference(kinds, amounts, start)
            );
        }

        #[test]
        fn invariants_hold_for_unconstrained_amounts(
            kinds in prop::collection::vec(0..=3_i64, 0..30),
            amounts in prop::collection::vec(0..=i64::MAX, 0..30),
            start in 0..=i64::MAX,
        ) {
            let n = kinds.len().min(amounts.len());
            let (bal, lines) = run_ledger(&kinds[..n], &amounts[..n], start);
            prop_assert!(bal >= 0);
            prop_assert_eq!(lines.len(), n);
            for &line in &lines {
                prop_assert!(line == -1 || line >= 0);
            }
            // The last accepted (non-rejected) line is the final balance,
            // or the final balance is the unchanged `start`.
            match lines.iter().rev().find(|&&l| l >= 0) {
                Some(&last) => prop_assert_eq!(last, bal),
                None => prop_assert_eq!(bal, start),
            }
            // Cross-check against the i128 reference.
            prop_assert_eq!(
                run_ledger(&kinds[..n], &amounts[..n], start),
                reference(&kinds[..n], &amounts[..n], start)
            );
        }

        #[test]
        fn apply_op_never_underflows(
            kind in 0..=3_i64,
            balance in 0..=i64::MAX,
            amount in 0..=i64::MAX,
        ) {
            let out = apply_op(kind, balance, amount);
            if let Some(b) = out {
                prop_assert!(b >= 0);
                if kind == 3 {
                    // a fee is always accepted and clamps at zero
                    prop_assert!(out.is_some());
                    prop_assert!(b <= balance);
                }
            }
        }
    }
}

/// Data for the report on a non-empty slice: smallest, largest,
/// midpoint floor((smallest + largest) / 2), number of elements strictly
/// greater than `t`, and the longest run of consecutive elements that are
/// all strictly greater than `t`.
#[derive(Debug, PartialEq, Eq, Clone, Copy)]
struct Report {
    smallest: i64,
    largest: i64,
    mid: i64,
    count_greater: i64,
    longest_run: i64,
}

/// Compute floor(n / 2) for an i128 `n` (Rust's `/` truncates toward zero).
fn floor_div2(n: i128) -> i128 {
    if n >= 0 {
        n / 2
    } else {
        (n - 1) / 2
    }
}

/// Compute the report data, or `None` if `a` is empty.
fn report_data(a: &[i64], t: i64) -> Option<Report> {
    if a.is_empty() {
        return None;
    }

    let mut smallest = a[0];
    let mut largest = a[0];
    let mut count_greater: i64 = 0;
    let mut longest_run: i64 = 0;
    let mut current_run: i64 = 0;

    for &x in a {
        if x < smallest {
            smallest = x;
        }
        if x > largest {
            largest = x;
        }
        if x > t {
            count_greater += 1;
            current_run += 1;
            if current_run > longest_run {
                longest_run = current_run;
            }
        } else {
            current_run = 0;
        }
    }

    // Exact floor((smallest + largest) / 2) with no i64 overflow:
    // the i128 sum fits (|sum| <= 2^65), and the midpoint lies in
    // [smallest, largest], so the result fits in i64.
    let sum = (smallest as i128) + (largest as i128);
    let mid = floor_div2(sum) as i64;

    Some(Report {
        smallest,
        largest,
        mid,
        count_greater,
        longest_run,
    })
}

/// Print a short report on `a` and return the length of the longest run of
/// consecutive elements that are all strictly greater than `t`.
///
/// If `a` is empty, prints nothing and returns 0. Otherwise prints four
/// lines: the smallest element, the largest element, the midpoint
/// floor((smallest + largest) / 2) (computed exactly, rounded toward
/// negative infinity), and the number of elements strictly greater than `t`.
pub fn report(a: &[i64], t: i64) -> i64 {
    match report_data(a, t) {
        None => 0,
        Some(r) => {
            println!("{}", r.smallest);
            println!("{}", r.largest);
            println!("{}", r.mid);
            println!("{}", r.count_greater);
            r.longest_run
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    fn longest_run_gt(a: &[i64], t: i64) -> i64 {
        let mut longest = 0i64;
        let mut cur = 0i64;
        for &x in a {
            if x > t {
                cur += 1;
                if cur > longest {
                    longest = cur;
                }
            } else {
                cur = 0;
            }
        }
        longest
    }

    fn expected_report(a: &[i64], t: i64) -> Option<Report> {
        if a.is_empty() {
            return None;
        }
        let smallest = a.iter().copied().min().unwrap();
        let largest = a.iter().copied().max().unwrap();
        // Independent exact midpoint via i128; the result lies in
        // [smallest, largest], so it fits in i64.
        let mid = super::floor_div2((smallest as i128) + (largest as i128)) as i64;
        let count_greater = a.iter().filter(|&&x| x > t).count() as i64;
        Some(Report {
            smallest,
            largest,
            mid,
            count_greater,
            longest_run: longest_run_gt(a, t),
        })
    }

    #[test]
    fn empty_returns_zero_with_no_data() {
        assert_eq!(report_data(&[], 42), None);
        // report on empty must return 0 (prints nothing).
        assert_eq!(report(&[], 42), 0);
        assert_eq!(report(&[], i64::MIN), 0);
        assert_eq!(report(&[], i64::MAX), 0);
    }

    #[test]
    fn simple_case() {
        // a = [3, 1, 2], t = 1
        // smallest 1, largest 3, mid floor(4/2) = 2, count > 1 is 2,
        // longest run > 1 is 1 (no two consecutive elements are both > 1).
        assert_eq!(report_data(&[3, 1, 2], 1), expected_report(&[3, 1, 2], 1));
        assert_eq!(
            report_data(&[3, 1, 2], 1),
            Some(Report {
                smallest: 1,
                largest: 3,
                mid: 2,
                count_greater: 2,
                longest_run: 1,
            })
        );
    }

    #[test]
    fn all_greater() {
        // a = [5, 6, 7], t = 0 -> all greater; run length 3, count 3, mid 6.
        assert_eq!(
            report_data(&[5, 6, 7], 0),
            Some(Report {
                smallest: 5,
                largest: 7,
                mid: 6,
                count_greater: 3,
                longest_run: 3,
            })
        );
        assert_eq!(report(&[5, 6, 7], 0), 3);
    }

    #[test]
    fn none_greater() {
        assert_eq!(
            report_data(&[5, 6, 7], 7),
            Some(Report {
                smallest: 5,
                largest: 7,
                mid: 6,
                count_greater: 0,
                longest_run: 0,
            })
        );
        assert_eq!(report(&[5, 6, 7], 7), 0);
    }

    #[test]
    fn single_element_equal_to_t() {
        assert_eq!(
            report_data(&[1], 1),
            Some(Report {
                smallest: 1,
                largest: 1,
                mid: 1,
                count_greater: 0,
                longest_run: 0,
            })
        );
        assert_eq!(report(&[1], 1), 0);
        assert_eq!(
            report_data(&[1], 0),
            Some(Report {
                smallest: 1,
                largest: 1,
                mid: 1,
                count_greater: 1,
                longest_run: 1,
            })
        );
        assert_eq!(report(&[1], 0), 1);
    }

    #[test]
    fn negative_midpoint_odd_sum_floors_down() {
        // a = [-7, -4], t = -10
        // smallest -7, largest -4, floor(-11/2) = -6, count 2, run 2.
        assert_eq!(
            report_data(&[-7, -4], -10),
            Some(Report {
                smallest: -7,
                largest: -4,
                mid: -6,
                count_greater: 2,
                longest_run: 2,
            })
        );
    }

    #[test]
    fn negative_midpoint_even_sum() {
        // a = [-7, -5], t = -10 -> floor(-12/2) = -6.
        assert_eq!(
            report_data(&[-7, -5], -10),
            Some(Report {
                smallest: -7,
                largest: -5,
                mid: -6,
                count_greater: 2,
                longest_run: 2,
            })
        );
    }

    #[test]
    fn no_overflow_at_extremes() {
        // smallest = i64::MIN, largest = i64::MAX; (MIN + MAX) = -1 overflows
        // i64, exact floor(-1/2) = -1. count > 0 is 1; run > 0 is 1.
        assert_eq!(
            report_data(&[i64::MIN, i64::MAX], 0),
            Some(Report {
                smallest: i64::MIN,
                largest: i64::MAX,
                mid: -1,
                count_greater: 1,
                longest_run: 1,
            })
        );
        assert_eq!(report(&[i64::MIN, i64::MAX], 0), 1);

        // Both at MIN: floor(2*MIN/2) = MIN.
        assert_eq!(
            report_data(&[i64::MIN, i64::MIN], i64::MIN),
            Some(Report {
                smallest: i64::MIN,
                largest: i64::MIN,
                mid: i64::MIN,
                count_greater: 0,
                longest_run: 0,
            })
        );
        // Both at MAX: floor(2*MAX/2) = MAX.
        assert_eq!(
            report_data(&[i64::MAX, i64::MAX], i64::MAX - 1),
            Some(Report {
                smallest: i64::MAX,
                largest: i64::MAX,
                mid: i64::MAX,
                count_greater: 2,
                longest_run: 2,
            })
        );
        // t = i64::MIN: nothing is strictly greater (x > MIN is false for MIN).
        assert_eq!(report(&[i64::MIN], i64::MIN), 0);
        // t = i64::MAX: nothing strictly greater.
        assert_eq!(report(&[i64::MAX], i64::MAX), 0);
        // t just below MAX.
        assert_eq!(
            report_data(&[i64::MAX], i64::MAX - 1),
            Some(Report {
                smallest: i64::MAX,
                largest: i64::MAX,
                mid: i64::MAX,
                count_greater: 1,
                longest_run: 1,
            })
        );
    }

    #[test]
    fn floor_div2_edges() {
        assert_eq!(floor_div2(0), 0);
        assert_eq!(floor_div2(1), 0);
        assert_eq!(floor_div2(2), 1);
        assert_eq!(floor_div2(3), 1);
        assert_eq!(floor_div2(-1), -1);
        assert_eq!(floor_div2(-2), -1);
        assert_eq!(floor_div2(-3), -2);
        assert_eq!(floor_div2(-(2i128 * (i64::MAX as i128))), -(i64::MAX as i128));
        assert_eq!(floor_div2(2i128 * (i64::MIN as i128)), i64::MIN as i128);
        assert_eq!(floor_div2(2i128 * (i64::MAX as i128)), i64::MAX as i128);
    }

    #[test]
    fn interleaved_runs() {
        // a = [1, 9, 9, 0, 2, 2, 2, 2, 8], t = 5
        // count > 5: 3 (the two 9s and the 8). Longest run: 2 ([9, 9]).
        // smallest 0, largest 9, mid floor(9/2) = 4.
        assert_eq!(
            report_data(&[1, 9, 9, 0, 2, 2, 2, 2, 8], 5),
            Some(Report {
                smallest: 0,
                largest: 9,
                mid: 4,
                count_greater: 3,
                longest_run: 2,
            })
        );
        assert_eq!(report(&[1, 9, 9, 0, 2, 2, 2, 2, 8], 5), 2);
    }

    #[test]
    fn runs_at_boundaries() {
        // Runs starting at the very beginning and ending at the very end.
        assert_eq!(report(&[2, 3, 1, 4, 5], 1), 2); // [2,3] vs [4,5] -> 2
        assert_eq!(report(&[2, 3, 4, 1, 5], 1), 3);
        assert_eq!(report(&[1, 2, 3, 4, 5], 1), 4);
        assert_eq!(report(&[5, 4, 3, 2, 1], 0), 5);
        assert_eq!(report(&[1, 0, 1, 0, 1], 0), 1);
        assert_eq!(report(&[0, 0, 0], 0), 0);
    }

    proptest! {
        #[test]
        fn report_data_matches_reference(
            a in proptest::collection::vec(any::<i64>(), 0..=64),
            t in any::<i64>()
        ) {
            let expected = expected_report(&a, t);
            prop_assert_eq!(report_data(&a, t), expected);
            // Return value of report matches the longest run (or 0 if empty).
            let run = expected.map(|r| r.longest_run).unwrap_or(0);
            prop_assert_eq!(report(&a, t), run);
        }

        #[test]
        fn midpoint_covers_extreme_pairs(
            s in any::<i64>(),
            l in any::<i64>()
        ) {
            // Check the midpoint against an independently written i128
            // reference for every (min, max) pair, including MIN/MAX.
            let (lo, hi) = (s.min(l), s.max(l));
            let got = report_data(&[lo, hi], 0).unwrap();
            let want_mid = {
                let sum = (lo as i128) + (hi as i128);
                // Independent floor division: for negative odd sums,
                // truncating division gives one too much; adjust.
                let mut m = sum / 2;
                if sum < 0 && sum % 2 != 0 {
                    m -= 1;
                }
                m as i64
            };
            prop_assert_eq!(got.smallest, lo);
            prop_assert_eq!(got.largest, hi);
            prop_assert_eq!(got.mid, want_mid);
            // mid must stay within [lo, hi].
            prop_assert!(got.mid >= lo && got.mid <= hi);
        }
    }
}

//! Token-bucket rate limiter.

/// Run a token-bucket rate limiter.
///
/// The bucket holds at most `cap` tokens; it starts full, with its refill
/// mark at time 0.  For each request `k` (arriving at `times[k]`, processed
/// in order):
///
/// 1. **Refill**: `g = (times[k] - mark) / every` whole periods have passed
///    since the mark, the bucket gains `g` tokens (never holding more than
///    `cap`), and the mark moves forward by `g * every`.
/// 2. **Serve**: if the bucket holds at least one token, the request is
///    accepted: one token is removed and `1` is printed; otherwise `0` is
///    printed.
///
/// Returns the number of accepted requests.
///
/// # Preconditions
///
/// * `times` is non-decreasing and every time is `>= 0`
/// * `cap >= 0`
/// * `every >= 1`
pub fn limiter(times: &[i64], cap: i64, every: i64) -> i64 {
    let mut tokens: i64 = cap; // bucket starts full
    let mut mark: i64 = 0; // refill mark
    let mut accepted: i64 = 0;

    for &t in times {
        // Invariant: `mark <= t`.  Initially `mark == 0 <= times[0]` (times
        // are non-negative); each update below only advances `mark` to at
        // most the current time, and times is non-decreasing.  Hence
        // `t - mark >= 0` (so plain integer division floors) and
        // `g * every <= t - mark`, so `mark + g * every <= t` (no overflow).
        let g = (t - mark) / every;
        mark += g * every;
        // `g` can be huge and `cap` can be `i64::MAX`, so apply the gain
        // without overflowing before capping.
        tokens = tokens.saturating_add(g).min(cap);

        if tokens >= 1 {
            tokens -= 1;
            accepted += 1;
            println!("{}", 1);
        } else {
            println!("{}", 0);
        }
    }

    accepted
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    /// Same algorithm expressed in `i128` so it can never overflow; used as
    /// an oracle for property tests.
    fn ref_limiter(times: &[i64], cap: i64, every: i64) -> i64 {
        let mut tokens: i128 = cap as i128;
        let mut mark: i128 = 0;
        let every = every as i128;
        let cap = cap as i128;
        let mut accepted = 0;
        for &t in times {
            let g = (t as i128 - mark) / every;
            mark += g * every;
            tokens = (tokens + g).min(cap);
            if tokens >= 1 {
                tokens -= 1;
                accepted += 1;
            }
        }
        accepted
    }

    #[test]
    fn empty() {
        assert_eq!(limiter(&[], 5, 1), 0);
    }

    #[test]
    fn zero_capacity_rejects_all() {
        assert_eq!(limiter(&[0, 1, 2, 3], 0, 1), 0);
    }

    #[test]
    fn burst_limited_by_capacity() {
        // all arrive at time 0: capacity 2 accepts two, rejects the third
        assert_eq!(limiter(&[0, 0, 0], 2, 1), 2);
    }

    #[test]
    fn refill_each_period() {
        assert_eq!(limiter(&[0, 1], 1, 1), 2);
        assert_eq!(limiter(&[0, 1, 2], 1, 1), 3);
    }

    #[test]
    fn mark_advances_by_whole_periods_only() {
        // t=0: g = 0/3 = 0, tok 1 -> accept -> 0, mark 0
        // t=5: g = 5/3 = 1, tok 0 -> 1, mark 3, accept -> 0
        // t=5: g = (5-3)/3 = 0, tok 0 -> reject
        assert_eq!(limiter(&[0, 5, 5], 1, 3), 2);
    }

    #[test]
    fn cap_is_applied_on_refill() {
        // t=0: g = 0, tok 5 -> accept -> 4
        // t=100: g = 100/3 = 33, tok min(4+33, 5) = 5, mark 99, accept -> 4
        // t=100: g = (100-99)/3 = 0, tok 4 -> accept -> 3
        assert_eq!(limiter(&[0, 100, 100], 5, 3), 3);
    }

    #[test]
    fn slow_refill() {
        // no whole period (every = 10) fits in the elapsed time
        assert_eq!(limiter(&[0, 1, 2], 1, 10), 1);
    }

    #[test]
    fn first_request_late() {
        // bucket starts full, one token is enough
        assert_eq!(limiter(&[10], 1, 1), 1);
    }

    #[test]
    fn hand_computed_sequence() {
        // t=0: g=0, tok 2 -> accept -> 1, mark 0
        // t=1: g=0, tok 1 -> accept -> 0
        // t=3: g=3/2=1, tok 1, mark 2 -> accept -> 0
        // t=6: g=(6-2)/2=2, tok 2, mark 6 -> accept -> 1
        assert_eq!(limiter(&[0, 1, 3, 6], 2, 2), 4);
    }

    #[test]
    fn extreme_values_no_overflow() {
        assert_eq!(limiter(&[i64::MAX], i64::MAX, 1), 1);
        assert_eq!(limiter(&[i64::MAX, i64::MAX], i64::MAX, 1), 2);
        assert_eq!(limiter(&[i64::MAX - 1, i64::MAX], i64::MAX, 2), 2);
        assert_eq!(limiter(&[i64::MAX], i64::MAX, i64::MAX), 1);
        assert_eq!(limiter(&[i64::MAX / 2, i64::MAX], i64::MAX, i64::MAX / 2), 2);
    }

    proptest! {
        #[test]
        fn matches_i128_reference_small(
            cap in 0..1_000i64,
            every in 1..1_000i64,
            times in prop::collection::vec(0..100_000i64, 0..100)
                .prop_map(|mut v| { v.sort_unstable(); v }),
        ) {
            assert_eq!(limiter(&times, cap, every), ref_limiter(&times, cap, every));
        }

        #[test]
        fn matches_i128_reference_big(
            cap in 0..=i64::MAX,
            every in 1..=i64::MAX,
            times in prop::collection::vec(0..=9_000_000_000_000_000_000u64, 0..50)
                .prop_map(|mut v| {
                    v.sort_unstable();
                    v.into_iter().map(i64::try_from).collect::<Result<Vec<i64>, _>>().unwrap()
                }),
        ) {
            assert_eq!(limiter(&times, cap, every), ref_limiter(&times, cap, every));
        }

        #[test]
        fn accepted_within_bounds_and_monotone_in_cap(
            cap in 0..1_000i64,
            every in 1..1_000i64,
            times in prop::collection::vec(0..10_000i64, 0..50)
                .prop_map(|mut v| { v.sort_unstable(); v }),
        ) {
            let a = limiter(&times, cap, every);
            prop_assert!(a >= 0 && a <= times.len() as i64);
            // the mark/gain schedule does not depend on the bucket level,
            // and a higher cap keeps the token level always >=, so a larger
            // cap can never accept fewer requests
            let b = limiter(&times, cap + 1, every);
            prop_assert!(b >= a);
        }
    }
}

//! Run-length encoding of a slice of i64 values.
//!
//! `rle` splits `a` into maximal runs of equal consecutive elements, splits
//! every run longer than `limit` into pieces of exactly `limit` elements
//! followed by one shorter piece for the rest (if any), prints each piece as
//! two lines (the element's value, then the piece's length) and returns the
//! total number of pieces.

/// Compute the pieces (value, length) in order, without printing.
fn pieces_of(a: &[i64], limit: i64) -> Vec<(i64, i64)> {
    debug_assert!(limit >= 1, "limit must be >= 1");
    let limit = limit as usize;
    let mut out: Vec<(i64, i64)> = Vec::new();
    let mut i = 0;
    while i < a.len() {
        let v = a[i];
        let mut j = i;
        while j < a.len() && a[j] == v {
            j += 1;
        }
        // Split the run [i, j) into limit-sized pieces plus a remainder.
        let mut rest = j - i;
        while rest > 0 {
            let piece = rest.min(limit);
            out.push((v, piece as i64));
            rest -= piece;
        }
        i = j;
    }
    out
}

/// Print a run-length encoding of `a` and return the number of pieces.
///
/// Splits `a` into maximal runs of equal consecutive elements; every run
/// longer than `limit` is split into pieces of exactly `limit` elements
/// followed by one shorter piece for the rest (if any rest remains), in
/// order. For each piece two lines are printed: the element's value, then
/// the piece's length. Returns the number of pieces (0 for an empty slice).
pub fn rle(a: &[i64], limit: i64) -> i64 {
    let ps = pieces_of(a, limit);
    for (v, len) in &ps {
        println!("{}", v);
        println!("{}", len);
    }
    ps.len() as i64
}

#[cfg(test)]
mod tests {
    use super::*;
    use proptest::prelude::*;

    #[test]
    fn empty_slice() {
        assert_eq!(rle(&[], 1), 0);
        assert_eq!(rle(&[], 100), 0);
    }

    #[test]
    fn single_element() {
        assert_eq!(rle(&[7], 1), 1);
        assert_eq!(rle(&[7], 5), 1);
    }

    #[test]
    fn all_equal_longer_than_limit() {
        // run of 5, limit 2 -> pieces 2,2,1
        let a = vec![1, 1, 1, 1, 1];
        assert_eq!(rle(&a, 2), 3);
        assert_eq!(pieces_of(&a, 2), vec![(1, 2), (1, 2), (1, 1)]);

        // run of 7, limit 3 -> pieces 3,3,1
        let b = vec![5, 5, 5, 5, 5, 5, 5];
        assert_eq!(rle(&b, 3), 3);
        assert_eq!(pieces_of(&b, 3), vec![(5, 3), (5, 3), (5, 1)]);

        // run of 6, limit 3 -> exactly 3,3
        let c = vec![9; 6];
        assert_eq!(rle(&c, 3), 2);
        assert_eq!(pieces_of(&c, 3), vec![(9, 3), (9, 3)]);
    }

    #[test]
    fn several_runs() {
        // runs: 1x1, 2x2, 3x3, limit 2 -> (1,1),(2,2),(3,2),(3,1)
        let a = vec![1, 2, 2, 3, 3, 3];
        assert_eq!(rle(&a, 2), 4);
        assert_eq!(
            pieces_of(&a, 2),
            vec![(1, 1), (2, 2), (3, 2), (3, 1)]
        );
    }

    #[test]
    fn limit_larger_than_runs() {
        let a = vec![1, 1, 2, 2, 2, 3];
        assert_eq!(rle(&a, 10), 3);
        assert_eq!(
            pieces_of(&a, 10),
            vec![(1, 2), (2, 3), (3, 1)]
        );
    }

    #[test]
    fn limit_one() {
        let a = vec![4, 4, 4, 5, 5];
        assert_eq!(rle(&a, 1), 5);
        assert_eq!(
            pieces_of(&a, 1),
            vec![(4, 1), (4, 1), (4, 1), (5, 1), (5, 1)]
        );
    }

    #[test]
    fn negative_and_extreme_values() {
        let a = vec![i64::MIN, i64::MIN, 0, i64::MAX, i64::MAX, i64::MAX];
        assert_eq!(rle(&a, 2), 4);
        assert_eq!(
            pieces_of(&a, 2),
            vec![
                (i64::MIN, 2),
                (0, 1),
                (i64::MAX, 2),
                (i64::MAX, 1),
            ]
        );
    }

    /// Sum of ceil(run_length / limit) over maximal runs of equal values.
    fn expected_count(a: &[i64], limit: i64) -> i64 {
        let mut expected: i64 = 0;
        let mut i = 0;
        while i < a.len() {
            let mut j = i;
            while j < a.len() && a[j] == a[i] {
                j += 1;
            }
            let l = (j - i) as i64;
            expected += (l + limit - 1) / limit;
            i = j;
        }
        expected
    }

    proptest! {
        #[test]
        fn prop_invariants(
            a in prop::collection::vec(any::<i64>(), 0..120),
            limit in 1_i64..=64,
        ) {
            let ps = pieces_of(&a, limit);

            // Total length preserved.
            let total: i64 = ps.iter().map(|&(_, l)| l).sum();
            prop_assert_eq!(total, a.len() as i64);

            // Piece lengths within [1, limit].
            for &(_, l) in &ps {
                prop_assert!(
                    1 <= l && l <= limit,
                    "piece length {} out of [1, {}]",
                    l, limit
                );
            }

            // Expanding the pieces reproduces a exactly.
            let mut expanded = Vec::with_capacity(a.len());
            for (v, l) in &ps {
                for _ in 0..*l {
                    expanded.push(*v);
                }
            }
            prop_assert_eq!(&expanded, &a);

            // No two adjacent equal-valued pieces can be merged into one piece.
            for w in ps.windows(2) {
                if w[0].0 == w[1].0 {
                    prop_assert!(
                        w[0].1 + w[1].1 > limit,
                        "adjacent equal pieces {:?} could be merged (limit {})",
                        w, limit
                    );
                }
            }

            // Count matches sum of ceil(run_len / limit), and rle returns it.
            let expected = expected_count(&a, limit);
            prop_assert_eq!(ps.len() as i64, expected);
            prop_assert_eq!(rle(&a, limit), expected);
        }

        #[test]
        fn prop_runs_and_limit(
            a in prop::collection::vec(0_i64..=4, 0..200),
            limit in 1_i64..=8,
        ) {
            let expected = expected_count(&a, limit);
            prop_assert_eq!(rle(&a, limit), expected);
        }

        #[test]
        fn prop_empty(limit in 1_i64..=100) {
            prop_assert_eq!(rle(&[], limit), 0);
            prop_assert!(pieces_of(&[], limit).is_empty());
        }
    }
}
